it('accepts list_sessions with optional limit and before cursor while stripping unknown fields and rejecting malformed ones', () => {
  const rejected = [
    {type: 'list_sessions', limit: 'ten'},
    {type: 'list_sessions', limit: -1},
    {type: 'list_sessions', limit: 1.5},
    {type: 'list_sessions', before: 'not-an-object'},
    {type: 'list_sessions', before: null},
    {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
    {type: 'list_sessions', before: {updatedAt: '2026-01-01T00.000Z', sessionId: 'a'.repeat(129)}},
    {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
    {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
  ].map(frame => validateMessage(frame).valid);

  expect({
    bare: validateMessage({type: 'list_sessions'}),
    withStringCursor: validateMessage({
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'},
      userId: 'u2',
    }),
    withNumberCursor: validateMessage({
      type: 'list_sessions',
      limit: 0,
      before: {updatedAt: 1700000000000, sessionId: 's1', extra: 'ignored'},
      userId: 'u2',
    }),
    rejected,
  }).toEqual({
    bare: {valid: true, data: {type: 'list_sessions'}},
    withStringCursor: {
      valid: true,
      data: {type: 'list_sessions', limit: 10, before: {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'}},
    },
    withNumberCursor: {
      valid: true,
      data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1700000000000, sessionId: 's1'}},
    },
    rejected: Array(9).fill(false),
  });
});

