it('accepts list_sessions with optional limit and before cursor while stripping unknown fields and rejecting malformed ones', () => {
  const validCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
  const invalidLimits = ['ten', -1, 1.5].map(limit => ({type: 'list_sessions', limit}));
  const invalidCursors = [
    'not-an-object',
    null,
    {...validCursor, sessionId: ''},
    {...validCursor, sessionId: 'a'.repeat(129)},
    {...validCursor, updatedAt: 'not-a-date'},
    {...validCursor, updatedAt: ['wrong']},
  ].map(before => ({type: 'list_sessions', before}));
  const invalid = [...invalidLimits, ...invalidCursors].filter(frame => !validateMessage(frame).valid);

  expect({
    bare: validateMessage({type: 'list_sessions'}),
    withStringCursor: validateMessage({type: 'list_sessions', limit: 10, before: validCursor, userId: 'u2'}),
    withNumberCursor: validateMessage({
      type: 'list_sessions',
      limit: 0,
      before: {updatedAt: 1700000000000, sessionId: 's1', extra: 'ignored'},
      userId: 'u2',
    }),
    rejectedCount: invalid.length,
  }).toEqual({
    bare: {valid: true, data: {type: 'list_sessions'}},
    withStringCursor: {valid: true, data: {type: 'list_sessions', limit: 10, before: validCursor}},
    withNumberCursor: {
      valid: true,
      data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1700000000000, sessionId: 's1'}},
    },
    rejectedCount: 9,
  });
});

